package io.github.long0823.tclbondriver;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.regex.*;
final class PhonePairing implements AutoCloseable {
 interface Listener {void done(String message);}
 final String code=String.format(Locale.ROOT,"%06d",new SecureRandom().nextInt(1000000));
 private final ServerSocket server;private volatile Socket client;private volatile boolean closed;private byte[] profile;private final Listener listener;private final long expires=System.nanoTime()+TimeUnit.SECONDS.toNanos(120);
 PhonePairing(byte[] data,Listener callback)throws IOException{profile=data;listener=callback;server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress(40559));server.setSoTimeout(1000);Thread thread=new Thread(this::serve,"phone-pairing");thread.setDaemon(true);thread.start();}
 private void serve(){int attempts=0;try{while(!closed&&System.nanoTime()<expires&&attempts<5){try(Socket s=server.accept()){client=s;s.setSoTimeout(2500);InputStream in=s.getInputStream();String first=line(in);int length=-1;boolean valid="POST /pair HTTP/1.1".equals(first);int count=0;String h;while(!(h=line(in)).isEmpty()){if(++count>30)throw new IOException();if(h.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(h.substring(15).trim());if(h.toLowerCase(Locale.ROOT).startsWith("transfer-encoding:"))valid=false;}attempts++;if(!valid||length!=6){reply(s,400,new byte[0]);continue;}byte[] supplied=new byte[6];new DataInputStream(in).readFully(supplied);if(!MessageDigest.isEqual(supplied,code.getBytes(StandardCharsets.US_ASCII))){reply(s,403,new byte[0]);continue;}if(closed||System.nanoTime()>=expires)break;reply(s,200,profile);listener.done("スマートフォンへ接続情報を送りました");return;}catch(SocketTimeoutException ignored){if(client!=null)System.err.println("PhonePairing: request timed out");}catch(Exception e){System.err.println("PhonePairing: request failed "+e.getClass().getSimpleName());attempts++;}finally{client=null;}}if(!closed)listener.done(attempts>=5?"確認コードの試行上限です。もう一度接続を開始してください":"確認コードの有効期限が切れました");}finally{close();}}
 private static String line(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();for(int n=0;n<1024;n++){int c=in.read();if(c<0)throw new EOFException();if(c==10)return b.toString("US-ASCII").replace("\r","");b.write(c);}throw new IOException();}
 private static void reply(Socket s,int status,byte[] data)throws IOException{OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 "+status+" Result\r\nContent-Type: application/octet-stream\r\nContent-Length: "+data.length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(data);out.flush();}
 public void close(){closed=true;try{server.close();}catch(Exception ignored){}Socket s=client;if(s!=null)try{s.close();}catch(Exception ignored){}profile=null;}
 static byte[] export(android.content.Context context)throws Exception {
  String token=capture("cat /data/local/tmp/tsd_token").trim();if(!token.matches("[a-fA-F0-9]{64}"))throw new IOException("TV配信の接続キーがありません。セットアップを確認してください。");
  String rows=capture("content query --uri content://android.media.tv/channel --projection display_number:original_network_id:transport_stream_id:service_id:type:service_type:browsable:display_name");
  Pattern pattern=Pattern.compile("(?m)^Row: \\d+ display_number=([^,\\r\\n]*), original_network_id=(\\d+), transport_stream_id=(\\d+), service_id=(\\d+), type=([^,\\r\\n]+), service_type=([^,\\r\\n]+), browsable=([01]), display_name=([^\\r\\n]*)\\r?$");
  ArrayList<String[]> channels=new ArrayList<>();HashSet<String> seen=new HashSet<>();Matcher m=pattern.matcher(rows);while(m.find()){if(!m.group(5).equals("TYPE_ISDB_T")||!m.group(7).equals("1")||(!m.group(6).equals("EN_TCL_DTV")&&!m.group(6).equals("SERVICE_TYPE_AUDIO_VIDEO")))continue;String key=m.group(2)+":"+m.group(3)+":"+m.group(4);if(!seen.add(key))continue;for(int i=2;i<=4;i++){int id=Integer.parseInt(m.group(i));if(id<1||id>65535)throw new IOException("局IDが不正です");}String name=m.group(8).trim(),number=m.group(1).trim();if(name.length()>160||name.isEmpty()||name.contains("\u0000")||number.length()>32)throw new IOException("局名が不正です");channels.add(new String[]{number,name,m.group(2),m.group(3),m.group(4)});if(channels.size()>512)throw new IOException("局数が多すぎます");}
  channels.sort((a,b)->{try{return Integer.compare(Integer.parseInt(a[0]),Integer.parseInt(b[0]));}catch(Exception e){return a[0].compareTo(b[0]);}});if(channels.isEmpty())throw new IOException("TVのチャンネルスキャンを完了してください。");StringBuilder ini=new StringBuilder("[Server]\nHost=127.0.0.1\n[Control]\nPort=40557\nTunerIndex=1\nToken=").append(token).append("\n[Channels]\nCount=").append(channels.size()).append('\n');int n=0;for(String[] c:channels)ini.append("[Channel").append(n++).append("]\nName=").append(c[1]).append("\nDisplayNumber=").append(c[0]).append("\nONID=").append(c[2]).append("\nTSID=").append(c[3]).append("\nServiceID=").append(c[4]).append('\n');ini.append("[IPTV]\nPort=40560\nAccessCode=").append(NetworkService.accessCode(context)).append("\nNetworkKeepalive=").append(context.getSharedPreferences(NetworkService.PREFS,0).getBoolean("enabled",false)?"1":"0").append("\n");return ini.toString().getBytes(StandardCharsets.UTF_8);
 }
 static String capture(String command)throws Exception {Process p=new ProcessBuilder("su","-c",command).redirectErrorStream(true).start();ByteArrayOutputStream out=new ByteArrayOutputStream();final boolean[] large={false};Thread drain=new Thread(()->{try(InputStream in=p.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0){if(out.size()+n<=2097152)out.write(b,0,n);else large[0]=true;}}catch(IOException ignored){}});drain.start();if(!p.waitFor(30,TimeUnit.SECONDS)){p.destroyForcibly();throw new IOException("TVのroot権限とスキャン状態を確認してください");}drain.join(3000);if(drain.isAlive()||large[0]||p.exitValue()!=0)throw new IOException("TVから設定を読み取れませんでした");return out.toString("UTF-8");}
}